from research_helpers import *
a=ev('https://www.sec.gov/Archives/edgar/data/1870144/000107997326000965/cdio_ars.htm','2025 annual report filed 2026 identifies two clinical tests, research offering, software and underlying technology. Laboratory-developed tests not recorded as FDA approved; software components overlap bundled test services.')
products=[]
for name,desc,sub,typ in [('Epi+Gen CHD','Laboratory-developed blood test assessing three-year coronary heart disease event risk.','diagnostics','product'),('PrecisionCHD','Laboratory-developed blood test aiding coronary heart disease detection.','diagnostics','product'),('CardioInnovate360','Research-use-only solution supporting cardiovascular biopharmaceutical discovery and validation.','research_tools','product'),('HeartRisk','Population cardiovascular risk intelligence software incorporating aggregated clinical-test data.','diagnostics','product'),('Actionable Clinical Intelligence','Provider-facing interpretation platform bundled with PrecisionCHD; not an additional independent laboratory assay.','diagnostics','technology'),('Cardio Diagnostics AI-driven Multi-Omics Engine','Genetic and epigenetic biomarker discovery and predictive modelling technology underpinning company tests.','research_tools','technology')]:products.append(p(name,desc,a,life='commercial',typ=typ,sub=sub))
co=dict(company_id='cmp_305d3967-0c0b-440b-b0ca-519dcb3cb3a5',products=products,evidence=[a],status='partial',coverage_note='Six current named tests, research/software offerings and supporting platforms recorded. Bundled Actionable Clinical Intelligence and underlying engine overlap clinical tests; not six independent assays. Partial: historical stroke, heart-failure and diabetes risk development programmes and newest 2026 portfolio updates require full review. No forecast launch assumed completed or FDA approval inferred.')
(out/'batch-0371.json').write_text(json.dumps({'companies':[co]},indent=2));print(len(products))
